import '/home/sunghoonk/Workspaces/OpenSmartFarmSim/web/e2e/joint-crop-climate-execution.spec.ts';
const cfg=JSON.parse(readFileSync(process.argv[2],'utf8'));const matching=cases.filter(c=>new RegExp(cfg.pattern).test(c.title));
if(matching.length!==1)throw Error('Expected exactly one declared browser case');
const server=spawn(cfg.nginx,['-p',cfg.directory,'-c',cfg.config,'-g','daemon off; master_process off; pid '+cfg.directory+'/static-nginx.pid;'],{stdio:['ignore','inherit','inherit']});
let browser;const output={runner:'single Node; unchanged Playwright case and hooks; real Chromium',cases:[]};
try{
 const deadline=Date.now()+10000;while(true){if(server.exitCode!==null||Date.now()>deadline)throw Error('static server unavailable');try{const r=await fetch(cfg.baseURL);if(r.ok)break;}catch{}await new Promise(r=>setTimeout(r,30));}
 browser=await chromium.launch({headless:true,args:['--enable-unsafe-swiftshader','--single-process','--no-zygote','--js-flags=--max-old-space-size=48 --max-semi-space-size=1 --expose-gc']});
