  try{for(const fn of after)await fn({page},info);}catch(error){failure??=error;info.status='failed';}
  await context.close();output.cases.push({...info,error:failure?String(failure):null});if(failure)throw failure;
 }
}finally{await browser?.close();server.kill('SIGTERM');await new Promise(resolve=>{if(server.exitCode!==null)resolve();else server.once('exit',resolve);});writeFileSync(cfg.output,JSON.stringify(output),{flag:'wx',mode:0o400});}
